sys_script_include.script:
var GetVendingMachineInfo = Class.create();
GetVendingMachineInfo.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getMachineInfo: function() {

        var id = this.getParameter('sysparm_machine_id');

        var gr = new GlideRecord('x_2005341_4dot_m_0_vending_machine_service');

        if (gr.get(id)) {

            return JSON.stringify({
                last_serviced: gr.last_serviced + "",
                state: gr.state + ""
            });
        }

        return JSON.stringify({
            last_serviced: "",
            state: ""
        });
    }
});
